function cardHtml(card) {
if (card.type === "joker") {
return `
      <div class="playing-card joker-card">
        <div class="joker-top">JOKER</div>
        <div class="joker-star">★</div>
        <div class="joker-bottom">JOKER</div>
      </div>
    `;
}
const suitCode = {"♠":"S","♥":"H","♦":"D","♣":"C"}[card.suit];
const localArt = `assets/${suitCode}${card.number}.png`;
const themedArt = `<img class="theme-card-art theme-pop-art" src="${TH\u0045MED_CARD_FACES[`card-pop-${suitCode}${card.number}`]}" alt="" draggable="false"><img class="theme-card-art theme-dark-art" src="${TH\u0045MED_CARD_FACES[`card-dark-${suitCode}${card.number}`]}" alt="" draggable="false">`;
if (card.number >= 11 && card.number <= 13) {
const code = `${suitCode}${card.number}`;
const art = (theme) => CO\u0055RT_CARD_ART[`${theme}-${code}`];
return `<div class="playing-card classic-card court-card"><img class="court-theme-art court-basic" src="${art('basic')}" alt="${nu\u006dberText(card.number)}${card.suit}" draggable="false"><img class="court-theme-art court-pop" src="${art('pop')}" alt="" draggable="false"><img class="court-theme-art court-dark" src="${art('dark')}" alt="" draggable="false"></div>`;
}
return `<div class="playing-card classic-card"><img class="classic-card-art" src="${localArt}" alt="${nu\u006dberText(card.number)}${card.suit}" draggable="false">${themedArt}</div>`;
}
function nu\u006dberText(number) {
if (number === 1) return "A";
if (number === 11) return "J";
if (number === 12) return "Q";
if (number === 13) return "K";
return String(number);
}
function ge\u0074CardClass(card) {
if (card.type === "joker") return "card-joker";
if (
card.suit === "♥" ||
card.suit === "♦"
) {
return "card-red";
}
return "card-black";
}
function shuffle(array) {
for (
let i = array.length - 1;
i > 0;
i--
) {
const j =
Math.floor(Math.random() * (i + 1));
[array[i], array[j]] =
[array[j], array[i]];
}
}
function re\u006ederSoloDonReveal() {
const r = ro\u0075ndFinished ? so\u006coDonReveal : null;
for (const [i,id] of [[0,"player-area"],[1,"cpu-left"],[2,"cpu-top"],[3,"cpu-right"]]) {
const seat=document.ge\u0074ElementById(id); if(!seat) continue;
const old=seat.qu\u0065rySelector(".solo-don-reveal");
const cards=r?.cards[i];
if(!cards?.length){old?.remove();continue;}
if(old)continue;
const box=document.cr\u0065ateElement("div");box.className="don-reveal solo-don-reveal";
const heading=document.cr\u0065ateElement("div");heading.te\u0078tContent=players[i].name+"："+(r.winners.includes(i)?"勝者・公開手札":"ドン勝負・公開手札");box.append(heading);
const row=document.cr\u0065ateElement("div");row.className="don-reveal-cards";
const ordered=cards.slice();sortHand(ordered);
for(const c of ordered){const art=document.cr\u0065ateElement("span");art.innerHTML=cardHtml(c);row.append(art);}box.append(row);
const b=r.breakdown[i];if(b){const calc=document.cr\u0065ateElement("div");calc.className="don-calculation";calc.te\u0078tContent=`残り${b.remaining}枚 × ${b.rate}点 × 役${b.ba\u0073eMultiplier}倍 × 親${b.pa\u0072entMultiplier}倍 × Joker ${b.jo\u006berMultiplier**b.jo\u006berCount}倍 ＝ ${b.perPayer}点／人`;box.append(calc);}
if(i===0)seat.in\u0073ertBefore(box,document.ge\u0074ElementById("hand"));else seat.append(box);
}
}
